raw_shacl_shapes:
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix domain: <http://sophia.ai/domain#> .

domain:VerdictClosedShape a sh:NodeShape ;
    sh:targetClass domain:Verdict ;
    sh:property [ sh:path domain:outcome ; sh:in ( domain:PASS domain:FAIL domain:BLOCKED ) ; sh:severity sh:Violation ] ;
    sh:property [ sh:path domain:targetSha256 ; sh:pattern "^[0-9a-f]{64}$" ; sh:severity sh:Violation ] ;
    sh:property [ sh:path domain:contentSha256 ; sh:pattern "^[0-9a-f]{64}$" ; sh:severity sh:Violation ] ;
    sh:property [ sh:path domain:evidence ; sh:class domain:EvidenceRef ; sh:severity sh:Violation ] .

domain:EvidenceDigestShape a sh:NodeShape ;
    sh:targetClass domain:EvidenceRef ;
    sh:property [ sh:path domain:contentSha256 ; sh:pattern "^[0-9a-f]{64}$" ; sh:severity sh:Violation ] .
